-- 000093_runtime_identity_hardening, down: restore the built-in rules as
-- 000080/000082 left them (by their new names; enabled untouched) and drop
-- match_comm_mode. Policies that were saved as 'word' or 'exact' fall back to
-- substring matching after the down step.

ALTER TABLE ebpf_trace_policies
    DROP CONSTRAINT IF EXISTS ebpf_trace_policies_match_comm_mode_check;
ALTER TABLE ebpf_trace_policies
    DROP COLUMN IF EXISTS match_comm_mode;

UPDATE trace_detection_rules SET name = 'Suppress runc process clone', description = 'runc clones namespaces during container startup. This is expected. Applies only below HIGH severity; process names alone do not justify hiding sensitive observations.', action = 'suppress', conditions = '[{"field":"comm","op":"starts_with","value":"runc"},{"field":"event_name","op":"eq","value":"clone"},{"field":"severity","op":"lte","value":2}]'::jsonb, severity_override = NULL, tags = ARRAY(SELECT jsonb_array_elements_text('["container","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade runc process clone';
UPDATE trace_detection_rules SET name = 'Suppress WAFio agent AF_NETLINK socket', description = 'WAFio agents create AF_NETLINK (family 16) sockets for network monitoring. This is expected. Applies only below HIGH severity; process names alone do not justify hiding sensitive observations.', action = 'suppress', conditions = '[{"field":"comm","op":"contains","value":"wafio"},{"field":"event_name","op":"eq","value":"socket"},{"field":"addr_family","op":"eq","value":16},{"field":"severity","op":"lte","value":2}]'::jsonb, severity_override = NULL, tags = ARRAY(SELECT jsonb_array_elements_text('["wafio","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade WAFio agent AF_NETLINK socket';
UPDATE trace_detection_rules SET name = 'Suppress systemd service start execve', description = 'systemd calls execve to start services. These are not process injection. Applies only below HIGH severity; process names alone do not justify hiding sensitive observations.', action = 'suppress', conditions = '[{"field":"comm","op":"eq","value":"systemd"},{"field":"event_name","op":"eq","value":"execve"},{"field":"severity","op":"lte","value":2}]'::jsonb, severity_override = NULL, tags = ARRAY(SELECT jsonb_array_elements_text('["systemd","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Suppress systemd service start execve';
UPDATE trace_detection_rules SET name = 'Suppress cron job execution', description = 'cron executing scheduled jobs via execve is normal operation. Applies only below HIGH severity; process names alone do not justify hiding sensitive observations.', action = 'suppress', conditions = '[{"field":"comm","op":"in","value":["cron","crond"]},{"field":"event_name","op":"eq","value":"execve"},{"field":"severity","op":"lte","value":2}]'::jsonb, severity_override = NULL, tags = ARRAY(SELECT jsonb_array_elements_text('["cron","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade cron job execution';
UPDATE trace_detection_rules SET name = 'Suppress logrotate log access', description = 'logrotate accessing /var/log is its intended purpose. Applies only below HIGH severity; process names alone do not justify hiding sensitive observations.', action = 'suppress', conditions = '[{"field":"comm","op":"eq","value":"logrotate"},{"field":"filename","op":"starts_with","value":"/var/log/"},{"field":"severity","op":"lte","value":2}]'::jsonb, severity_override = NULL, tags = ARRAY(SELECT jsonb_array_elements_text('["logrotate","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade logrotate log access';
UPDATE trace_detection_rules SET name = 'Suppress apt/dpkg package management', description = 'apt and dpkg running execve during package operations is expected. Applies only below HIGH severity; process names alone do not justify hiding sensitive observations.', action = 'suppress', conditions = '[{"field":"comm","op":"in","value":["apt","apt-get","dpkg","dpkg-deb","apt-cache"]},{"field":"event_name","op":"eq","value":"execve"},{"field":"severity","op":"lte","value":2}]'::jsonb, severity_override = NULL, tags = ARRAY(SELECT jsonb_array_elements_text('["package-manager","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade apt/dpkg package management';
UPDATE trace_detection_rules SET name = 'Suppress local health-check curl', description = 'curl connecting to 127.0.0.1 or localhost is typically a health check probe. Applies only below HIGH severity; process names alone do not justify hiding sensitive observations.', action = 'suppress', conditions = '[{"field":"comm","op":"eq","value":"curl"},{"field":"addr","op":"eq","value":"127.0.0.1"},{"field":"severity","op":"lte","value":2}]'::jsonb, severity_override = NULL, tags = ARRAY(SELECT jsonb_array_elements_text('["health-check","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade local health-check curl';
UPDATE trace_detection_rules SET name = 'Suppress dockerd network management', description = 'dockerd creating/managing network sockets is normal container networking. Applies only below HIGH severity; process names alone do not justify hiding sensitive observations.', action = 'suppress', conditions = '[{"field":"comm","op":"eq","value":"dockerd"},{"field":"category","op":"eq","value":"network"},{"field":"severity","op":"lte","value":2}]'::jsonb, severity_override = NULL, tags = ARRAY(SELECT jsonb_array_elements_text('["docker","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Suppress dockerd network management';
UPDATE trace_detection_rules SET name = 'Downgrade sshd host key reads', description = 'sshd loads its own host keys on every connection. Reading /etc/ssh/* is the daemon doing its job.', action = 'downgrade', conditions = '[{"field":"comm","op":"eq","value":"sshd"},{"field":"parent_comm","op":"eq","value":"sshd"},{"field":"event_name","op":"eq","value":"openat"},{"field":"filename","op":"starts_with","value":"/etc/ssh/"},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb, severity_override = 1, tags = ARRAY(SELECT jsonb_array_elements_text('["ssh","expected"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade sshd host key reads';
UPDATE trace_detection_rules SET name = 'Downgrade sshd account database reads', description = 'sshd reads the account database during authentication and session setup.', action = 'downgrade', conditions = '[{"field":"comm","op":"eq","value":"sshd"},{"field":"parent_comm","op":"eq","value":"sshd"},{"field":"event_name","op":"eq","value":"openat"},{"field":"filename","op":"in","value":["/etc/passwd","/etc/shadow","/etc/group","/etc/gshadow","/etc/nsswitch.conf"]},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb, severity_override = 1, tags = ARRAY(SELECT jsonb_array_elements_text('["ssh","auth","expected"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade sshd account database reads';
